import ezdxf
doc = ezdxf.readfile("workspace/input/ada_bath_input.dxf")
msp = doc.modelspace()

def poly_pts(e):
    if e.dxftype() == "LWPOLYLINE":
        return [(p[0], p[1]) for p in e.get_points(format="xy")], bool(e.closed)
    pts = [(v.dxf.location.x, v.dxf.location.y) for v in e.vertices]
    return pts, bool(e.close)

for layer in ["FIXT-TUB", "FIXTURE-LAV", "FIXTURE-WC", "GRABRAIL"]:
    print("="*20, layer, "="*20)
    for e in msp.query(f'*[layer=="{layer}"]'):
        t = e.dxftype()
        if t == "LINE":
            print(f"  LINE: ({e.dxf.start.x:.3f},{e.dxf.start.y:.3f}) -> ({e.dxf.end.x:.3f},{e.dxf.end.y:.3f})")
