        elif t == "ARC":
            print(f"  ARC: c=({e.dxf.center.x:.3f},{e.dxf.center.y:.3f}) r={e.dxf.radius:.3f} a0={e.dxf.start_angle:.1f} a1={e.dxf.end_angle:.1f}")
        elif t in ("POLYLINE","LWPOLYLINE"):
            pts, closed = poly_pts(e)
            print(f"  {t} closed={closed}: " + " ".join(f"({x:.3f},{y:.3f})" for x,y in pts))
        elif t == "SPLINE":
            pts = list(e.control_points)
            print(f"  SPLINE: " + " ".join(f"({p[0]:.3f},{p[1]:.3f})" for p in pts))
        elif t == "POINT":
            print(f"  POINT: ({e.dxf.location.x:.3f},{e.dxf.location.y:.3f})")
