      const bytes = await fs.readFile(path.join(directory, file));
      const content = (file.endsWith('.gz') ? gunzipSync(bytes) : bytes).toString('utf8');
      for (const line of content.split('\n')) {
        let entry;
        try { entry = JSON.parse(line); } catch { continue; }
