for (const signal of ['SIGTERM', 'SIGINT']) {
  process.once(signal, () => app.close().then(() => process.exit(0)).catch(() => process.exit(1)));
}
await app.start();
console.log(JSON.stringify({ event: 'nextagent.bench.started', pid: process.pid }));

